import { spawn } from 'child_process';
import path from 'path';
import fs from 'fs';
export function findCodegenCli(baseDir = process.cwd()) {
    // Check relative locations for wavemaker-ng-codegen
    const possiblePaths = [
        path.resolve(baseDir, '../wavemaker-ng-codegen/dist/codegen/codegen-app/src/codegen-args-cli.js'),
        path.resolve(baseDir, '../../wavemaker-ng-codegen/dist/codegen/codegen-app/src/codegen-args-cli.js'),
        path.resolve(process.env.HOME || '', '.wm/node_modules/@wavemaker/angular-codegen/build-angular-app.js')
    ];
    for (const p of possiblePaths) {
        if (fs.existsSync(p))
            return p;
    }
    return null;
}
export async function runMonitoredCodegen(options, monitor) {
    const projectName = options.projectName || path.basename(options.unzippedProjectPath);
    const targetAppPath = path.join(options.targetFolder, projectName);
    const codegenCli = options.codegenRepoPath || findCodegenCli();
    if (!codegenCli || !fs.existsSync(codegenCli)) {
        throw new Error(`wavemaker-ng-codegen CLI not found. Please ensure wavemaker-ng-codegen is built at '../wavemaker-ng-codegen/dist/codegen/codegen-app/src/codegen-args-cli.js'`);
    }
    // 'target/ui-resources' (wmProperties.js, font.config.js, servicedefs/, prefabs/, ...) is a
    // hard prerequisite for codegen, but it's produced by WaveMaker Studio's own backend server at
    // design time — no Maven CLI goal in any published version of wavemaker-studio-maven-plugin
    // generates it. A bare WM Source project exported straight from Studio (or downloaded without
    // ever being opened/built inside it) won't have this folder, and codegen fails deep inside
    // ng-codegen's internals with an opaque, hard-to-diagnose error if it's missing. Fail fast
    // here instead, with an actionable message.
    const uiResourcesPath = path.join(options.unzippedProjectPath, 'target', 'ui-resources');
    if (!fs.existsSync(uiResourcesPath)) {
        throw new Error(`'target/ui-resources' not found at '${uiResourcesPath}'. This folder (wmProperties.js, font.config.js, ` +
            `servicedefs/, prefabs/) is generated by WaveMaker Studio's backend server at design time, not by any ` +
            `Maven CLI goal — 'mvn clean process-classes' alone will not produce it. Open/build this project in ` +
            `WaveMaker Studio at least once (or copy its 'target/ui-resources' folder into this project) before ` +
            `running codegen/monitor against it.`);
    }
    // `--codegenPath` (passed as '.' below) is resolved by ng-codegen relative to `cwd`, and it's
    // used to locate 'templates/', 'dependencies/' and 'pwa-assets/' — which live in the
    // codegen-app root, one level ABOVE the 'src/' folder that codegen-args-cli.js itself lives
    // in. Spawning with cwd = the cli's own directory (src/) makes ng-codegen look for
    // 'src/templates/...', which doesn't exist, and it fails with ENOENT.
    const cliDir = path.dirname(codegenCli);
    const codegenDir = path.basename(cliDir) === 'src' ? path.dirname(cliDir) : cliDir;
    monitor.setPhase('Codegen Transpilation');
    const args = [
        codegenCli,
        '-s', path.resolve(options.unzippedProjectPath),
        '-t', path.resolve(targetAppPath),
        '--codegenPath', '.',
        '--spa', 'true'
    ];
    return new Promise((resolve, reject) => {
        const child = spawn('node', args, {
            cwd: codegenDir,
            stdio: ['ignore', 'pipe', 'pipe']
        });
        if (child.pid) {
            monitor.start(child.pid);
        }
        let stderr = '';
        child.stderr?.on('data', data => (stderr += data.toString()));
        child.on('close', code => {
            const report = monitor.generateReport(projectName);
            if (code === 0) {
                installDependencies(targetAppPath)
                    .then(() => resolve({ success: true, generatedAppPath: targetAppPath, report }))
                    .catch(reject);
            }
            else {
                reject(new Error(`Codegen failed with exit code ${code}. Error: ${stderr}`));
            }
        });
    });
}
// Codegen only links local packages via `yalc add` — it never runs a full `npm install`, so
// `@angular/cli` and every other real dependency are still missing from the generated app's
// `node_modules` at this point. `runMonitoredBuild`'s own node_modules-exists check passes
// anyway (yalc already created the directory), so without this step the build phase fails deep
// inside `ng build` with an opaque 'node_modules/.bin/ng: No such file or directory' instead of
// a clear, actionable error.
function installDependencies(appDir) {
    console.log(`\n📦 Installing dependencies in generated app: ${appDir}\n`);
    return new Promise((resolve, reject) => {
        const child = spawn('npm', ['install', '--no-audit', '--no-fund'], {
            cwd: appDir,
            stdio: ['ignore', 'pipe', 'pipe']
        });
        let stderr = '';
        child.stderr?.on('data', data => (stderr += data.toString()));
        child.on('close', code => {
            if (code === 0) {
                console.log(`✅ Dependencies installed.`);
                resolve();
            }
            else {
                reject(new Error(`npm install failed with exit code ${code} in '${appDir}'. Error: ${stderr}`));
            }
        });
        child.on('error', reject);
    });
}
